"""Write docs/validation-expansion-2026-11.md from the committed tables in data/validation/.
Usage: python -I write_expansion_doc.py <repo>"""
import sys, csv, json

repo = sys.argv[1]; V = f"{repo}/data/validation"
rd = lambda name: list(csv.DictReader(open(f"{V}/{name}")))
knee = rd("sync21-knee-summary.csv"); trials = rd("sync21-knee-trials.csv")
pulse = rd("mcd-scale-pulse.csv"); gate = rd("mcd-scale-live-gate.csv")
gsel = lambda g, half: next(r for r in gate if float(r["gate"]) == g and r["half"] == half and r["camera"] == "all three")
chg = rd("mcd-scale-rest-vs-squats.csv"); hrv = rd("mcd-scale-hrv.csv")
worst = json.load(open(f"{V}/mcd-scale-summary.json")).get("hybrid_worst_bpm")
S = json.load(open(f"{V}/mcd-scale-summary.json"))
k = {(r["movement"], r["camera"]): r for r in knee}
p = lambda cam, state, method: next(r for r in pulse if r["camera"] == cam and r["state"] == state and r["method"].startswith(method))
CAMS = ["front webcam", "phone camera (Iriun)", "side USB camera", "all three"]
hy = {c: p(c, "both", "Self-check hybrid (as shipped") for c in CAMS}
h0 = {c: p(c, "both", "Self-check hybrid, gate off") for c in CAMS}
lo = {c: p(c, "both", "Live Capture colour pulse, earlier") for c in CAMS}
ln = {c: p(c, "both", "Live Capture colour pulse, gate 0.5") for c in CAMS}
f = lambda r, key, unit="": "–" if r[key] in ("", None) else f"{r[key]}{unit}"
answered = [h for h in hrv if h["camera_rmssd_ms"]]
reasons = {}
for h in hrv:
    if h["refused_reason"]: reasons[h["refused_reason"]] = reasons.get(h["refused_reason"], 0) + 1
top = sorted(reasons.items(), key=lambda kv: -kv[1])[:3]
sq, sqf, lu = k[("Squat", "side-on")], k[("Squat", "facing")], k[("Lunges", "side-on")]

L = []
w = L.append
w("# Validation expansion, November 2026")
w("")
w("Added after the Space Apps 2026 local round, on the `post-judging-upgrades` branch. The submitted app (commit 524852f) is unchanged; "
  "everything here is new evidence on new people, plus the fixes it led to. Generated by `scripts/validation/write_expansion_doc.py` from the tables in `data/validation/`.")
w("")
w("## Summary")
w("")
w(f"- **Every headline number checked.** `scripts/audit-claims.mjs` recomputes the README's and the submission's numbers (NASA DONKI and ISS dose counts, OSD-804 statistics, the Inspiration4 replay, report size, the false-alarm simulation, the knee and pulse results) from the shipped code and data. All reproduce; `src/claimsAudit.test.js` keeps it that way.")
w(f"- **Knee, a second lab and 19 more people.** On an independent CC BY 4.0 dataset (21 men, OptiTrack motion capture, two smartphones), the side-on 2D knee angle that the app's knee model falls back on read squat range of motion within {sq['rom_mae_deg']}° per repetition (bias {sq['rom_bias_deg']}°); facing the camera the 2D angle was {sqf['rom_mae_deg']}° off. This is the reason the self-check asks people to sit side-on, now confirmed outside REHAB24-6. Repeat noise side-on: ±{sq['rom_repeat_sd_deg']}° (range of motion), below the ±5.8° the app already uses, so the app's figure is the cautious one.")
w(f"- **Camera pulse on {S['people']} new people and three cameras, one a phone.** The self-check pulse, as shipped, answered {hy['front webcam']['answered_pct']} % of 30-second windows on the front webcam, {hy['phone camera (Iriun)']['answered_pct']} % on the phone and {hy['side USB camera']['answered_pct']} % on the side camera, and was within {hy['all three']['mae_bpm']} bpm of the finger sensor on average when it answered ({hy['all three']['within_5_bpm_pct']} % within 5 bpm). With its quality gate switched off it would have answered {h0['all three']['answered_pct']} % at {h0['all three']['mae_bpm']} bpm ({h0['phone camera (Iriun)']['mae_bpm']} bpm on the phone): the gate is what keeps most wrong numbers off the screen. It does not catch all: {round(100 - float(hy['all three']['within_5_bpm_pct']), 1)} % of its answers were more than 5 bpm off (worst {worst} bpm). One such reading just outside the usual range asks for a re-check, but one far outside goes to review, so these remain a source of false alarms.")
w(f"- **Live Capture heart-rate variability removed.** Its camera RMSSD answered {S['hrv_answered']} of {S['videos']} recordings, {S['hrv_mae_ms']} ms from the finger sensor on average when it did. The number is no longer shown; the panel says why.")
w(f"- **Live Capture pulse gate raised from 0.3 to 0.5.** Its colour-only wave locked onto an artefact near 50 bpm on the phone and side cameras ({lo['phone camera (Iriun)']['mae_bpm']} and {lo['side USB camera']['mae_bpm']} bpm average error when it answered at 0.3). Choosing on half of the people picked 0.45 (worst reading {gsel(0.45, 'choose')['max_error_bpm']} bpm), but on the other half 0.45 still let a reading {gsel(0.45, 'check')['max_error_bpm']} bpm off through; at 0.5 the worst on either half was {max(float(gsel(0.5, 'choose')['max_error_bpm']), float(gsel(0.5, 'check')['max_error_bpm']))} bpm. So 0.5 was chosen after seeing both halves, and has no clean hold-out yet. At 0.5 it answers {f(ln['all three'], 'answered_pct', ' %')} of windows ({f(ln['front webcam'], 'answered_pct', ' %')} on the front webcam). Live Capture's colour-only pulse is a demonstration; the self-check's 45-second camera minute is the reading to use.")
w("- **Still not tested:** darker skin tones (MCD-rPPG has no skin-type labels, and the face colour the three cameras record for the same person differs too much to sort people by it), the seated knee test against a goniometer, the breathing check against a belt (no open video dataset with a belt signal could be downloaded: the MPSC-RR videos are CC BY 4.0 but their belt signals are not published), Bluetooth import with a real cuff, and anyone in space.")
w("")
w("## 1. Claim audit")
w("")
w("`node scripts/audit-claims.mjs` (add `--tests` to also run `npm test` and check the README's test count). Each line recomputes one claim from the code and data that ship, and checks that the README still states it. The two 60-day simulations take about 45 s each; `--quick` skips them, and that quick form runs inside `npm test`.")
w("")
w("## 2. Knee: a second, independent lab dataset")
w("")
w("**Data.** *A Synchronized Dual-System Marker-based and Markerless Motion Capture Dataset for Gait and Fundamental Fitness Activities* (Capital University of Physical Education and Sports, 2026; doi:10.5281/zenodo.19720803; CC BY 4.0): 21 male students, OptiTrack markers at 120 Hz, two smartphones (front and side). "
  "The dataset publishes the phones' YOLOv8n-pose keypoints, not the videos, so this tests the app's knee geometry and repetition rules with another model's keypoints, not the app's MediaPipe pipeline.")
w("")
w("**Method** (`scripts/validation/sync21_knee.py`). Truth: the interior knee angle from Harrington hip-joint centres and the lateral knee and ankle markers. Camera: the 2D image-plane angle hip-knee-ankle (keypoint confidence ≥ 0.5), which is the app's fixed side-on rule. "
  "Each trial was aligned by searching frame rate and offset for the best correlation; repetitions run between the deepest bends; extension = 95th percentile of the angle, range of motion = extension minus the deepest bend, as in the app. Only the knee the camera saw better counts (the app's near-knee rule). Repeat noise: mean difference between consecutive repetitions' errors / 1.128.")
w("")
w("| Movement, camera | People | Reps | True range | Range error (mean abs.) | Bias | Repeat noise | MDC95 | Extension error | Trace correlation |")
w("|---|---|---|---|---|---|---|---|---|---|")
for r in knee:
    w(f"| {r['movement']}, {r['camera']} | {r['people']} | {r['reps']} | {r['true_rom_deg']}° | {r['rom_mae_deg']}° | {r['rom_bias_deg']}° | ±{r['rom_repeat_sd_deg']}° | {r['rom_mdc95_deg']}° | {r['ext_mae_deg']}° | {r['median_trace_corr']} |")
w("")
w(f"**Reading it.** Side-on squats agree closely (median trace correlation {sq['median_trace_corr']}, range error {sq['rom_mae_deg']}°, no bias). Facing the camera, the 2D angle loses depth and reads the range {abs(float(sqf['rom_bias_deg']))}° too small, the same failure REHAB24-6 showed for MediaPipe's 3D angle; the app's learned trees exist for that case. "
  f"Lunges are harder even side-on ({lu['rom_mae_deg']}°): the legs cross and the far knee hides the near one. The self-check's test is a seated knee extension, a single-joint movement in one plane, closer to the squat than to the lunge, but it still needs its own goniometer check.")
w("")
w("## 3. Camera pulse on more people and three cameras")
w("")
w(f"**Data.** MCD-rPPG (Egorov et al., 2025; CC BY 4.0): {S['people']} people not used before (picked at random, seed 2026; the 6 who overlapped the first 40 are left out), each filmed at rest and right after 15 squats by three cameras at once: a front webcam (640 × 480), a phone streamed over Iriun and a USB camera to the side. "
  f"First 60 s of each recording ({S['videos']} recordings, {S['windows']} windows of 30 s every 10 s); truth is the frame-synchronised finger PPG.")
w("")
w("**Method.** `scripts/validation/mcd_scale_worker.py` runs the face mesh, the app's skin regions and ME-rPPG through the app's own ONNX file with the app's face-mesh crop; `score-scale.mjs` then scores the app's JavaScript as shipped (`fusedPulseFromSamples`, `colourPulseFromSamples`, `estimateStress`).")
w("")
w("| Camera | Method | People | Windows | Answered | Error when answered | Within 5 bpm |")
w("|---|---|---|---|---|---|---|")
for c in CAMS:
    for r in (hy[c], h0[c], lo[c], ln[c]):
        w(f"| {c} | {r['method']} | {r['people']} | {r['windows']} | {r['answered_pct']} % | {f(r, 'mae_bpm', ' bpm')} | {f(r, 'within_5_bpm_pct', ' %')} |")
w("")
w("**Reading it.** The deep-led hybrid is as accurate on the phone and the side camera as on the front webcam whenever it answers; it answers less often there, because those streams carry a weaker pulse. Without the gate the phone readings would have been about 10 bpm off on average. Refusing is the behaviour the app is designed for: a refused reading asks for a repeat, a wrong one would move the baseline.")
w("")
if chg:
    w("**Rest → after squats, per camera** (first 30 s window of each, both answered):")
    w("")
    w("| Camera | People | Both answered | Change error | r | True rise |")
    w("|---|---|---|---|---|---|")
    for r in chg:
        w(f"| {r['camera']} | {r['people']} | {r['both_answered']} | {r['change_mae_bpm']} bpm | {r['change_r']} | {r['true_rise_bpm']} bpm |")
    w("")
w("**Live Capture gate** (`data/validation/mcd-scale-live-gate.csv`; people sorted by id, every other one chooses, the rest check):")
w("")
w("| Gate | Half | Answered | Error when answered | Worst reading |")
w("|---|---|---|---|---|")
for r in gate:
    if r["camera"] == "all three": w(f"| {r['gate']} | {r['half']} | {r['answered_pct']} % | {f(r, 'mae_bpm', ' bpm')} | {f(r, 'max_error_bpm', ' bpm')} |")
w("")
w("## 4. Live Capture heart-rate variability")
w("")
w(f"Live Capture used to show RMSSD from the face colour (`estimateStress` in `src/rppg.js`) after 30 s of steady video. It had only been checked on a synthetic face video. On the {S['videos']} new recordings (first 60 s, as Live Capture would run it), it answered {S['hrv_answered']} times; the finger PPG's RMSSD over the same 60 s was the reference. "
  f"When it answered it was {S['hrv_mae_ms']} ms off on average (median ratio camera / finger {S['hrv_ratio']}). Most often it refused with: " + "; ".join(f"\"{k}\" ({v})" for k, v in top) + ". "
  "At 30 frames a second, colour noise moves each beat's timing by more than the beat-to-beat changes RMSSD measures. The app no longer shows the number (`PulseCapture` with `variability: false` in `src/healthLayers.js`); the panel shows these figures instead (`LIVE_VARIABILITY_CHECK` in `src/cameraPulse.js`). Per-recording values: `data/validation/mcd-scale-hrv.csv` (the ECG column is a 30-second strip recorded separately, a second reference).")
w("")
w("## 5. Limits")
w("")
w("- MCD-rPPG people were recorded in one country, mostly with light skin; no skin type is recorded. Darker skin tones remain untested.")
w("- The second knee dataset is 21 young men, and it gives another model's 2D keypoints, not video, so the app's own pose model and hybrid trees were not run on it.")
w("- Everything here is healthy adults on Earth.")
w("")
w("## 6. Rerun")
w("")
w("```sh")
w("node scripts/audit-claims.mjs                    # claims; --quick skips the simulations, --tests adds npm test")
w("python -I scripts/validation/sync21_knee.py <dataset dir> <out dir>   # unzip Zenodo 19720803 files 02 and 03 first")
w("python -I scripts/validation/mcd_scale_worker.py jobs.txt <npz dir> 60 <shard> <shards>   # rows: person camera state")
w("python -I scripts/validation/mcd_scale_export.py <npz dir> <ecg dir> <signals dir>")
w("node scripts/validation/score-scale.mjs <signals dir> scale.json")
w("python -I scripts/validation/summarize_scale.py scale.json <repo>")
w("python -I scripts/validation/write_expansion_doc.py <repo>")
w("```")
open(f"{repo}/docs/validation-expansion-2026-11.md", "w").write("\n".join(L) + "\n")
print("written", len(L), "lines")
